import{c as r,Q as a,j as t,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"CacheWeaver: Cache-Aware Evidence Ordering for Efficient Grounded RAG Inference","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.19667","title":"CacheWeaver: Cache-Aware Evidence Ordering for Efficient Grounded RAG Inference","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.19667,"authors":["Kaizhen Tan","Rong Gu","Mingyuan Li"],"domains":["cs.CL","prompt caching"],"html":"https://arxiv.org/html/2606.19667v1","pdf_path":"pdfs/2606.19667.pdf","published_date":"2026-06-18T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-18-cacheweaver-cache-aware-evidence-ordering-rag-2606-19667.md","filePath":"research/papers/2026-06-18-cacheweaver-cache-aware-evidence-ordering-rag-2606-19667.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-06-18-cacheweaver-cache-aware-evidence-ordering-rag-2606-19667.md"};function o(c,e,s,l,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="cacheweaver-cache-aware-evidence-ordering-for-efficient-grounded-rag-inference" tabindex="-1">CacheWeaver: Cache-Aware Evidence Ordering for Efficient Grounded RAG Inference <a class="header-anchor" href="#cacheweaver-cache-aware-evidence-ordering-for-efficient-grounded-rag-inference" aria-label="Permalink to &quot;CacheWeaver: Cache-Aware Evidence Ordering for Efficient Grounded RAG Inference&quot;">​</a></h1><p><strong>Authors</strong>: Kaizhen Tan, Rong Gu, Mingyuan Li <strong>Published</strong>: June 18, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.19667" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.19667</a> · <a href="https://arxiv.org/html/2606.19667v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.19667 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.19667" target="_blank" rel="noreferrer">research/papers/pdfs/2606.19667.pdf</a> (9 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Retrieval-Augmented Generation (RAG) improves factual grounding, but it also lengthens prompts and raises prefill cost. Prefix caching in serving engines such as vLLM reduces this cost only when requests share the same token prefix. In grounded generation, however, adjacent queries may retrieve overlapping evidence in different orders, so set overlap does not become reusable prefix overlap. We present CacheWeaver, a lightweight prompt-layer method for cache-aware evidence ordering. The method keeps a prefix tree over recently served evidence sequences and uses a greedy walk to place the most reusable prefix first, while leaving the serving engine and retrieved evidence set unchanged. Across three vLLM configurations, the method lowers median time-to-first-token (TTFT) by about 20-33 percent relative to retrieval-order prefix caching, without hurting answer quality in our QA tests. The greedy policy reaches 97.5 percent of the median TTFT gain from oracle ordering, indicating that most reusable prefix locality can be recovered by a simple scheduling layer between retrieval and inference.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>CacheWeaver</strong>：在 retrieval 與 inference 之間插入輕量 prompt-layer scheduling，重新排列 evidence 順序以最大化 prefix cache 命中率。</li><li>維護 <strong>prefix tree</strong>（前綴樹）追蹤近期已服務的 evidence 序列，以 greedy walk 選出最長可重用前綴優先放置，不修改 serving engine（vLLM）或 retrieved evidence set。</li><li>目標指標：<strong>TTFT（time-to-first-token）</strong>，即 prefill 延遲；在不影響答題品質的前提下降低推論成本。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>跨三種 vLLM 配置，median TTFT 相較 retrieval-order prefix caching 降低約 <strong>20–33%</strong>。</li><li>Greedy policy 達到 oracle ordering 可得 median TTFT 增益的 <strong>97.5%</strong>，顯示簡單排程即可回收絕大多數 prefix locality。</li><li>QA 品質測試中未觀測到答題品質下降。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未設獨立 limitation 章節；可判斷的弱點： <ul><li>Prefix tree 效益依賴相鄰請求間 evidence 重疊率高，低重疊場景（如高多樣性查詢流）增益有限。</li><li>評估僅在 vLLM 上進行，跨 serving engine（TGI、TensorRT-LLM 等）泛化性未驗證。</li><li>僅報告 median TTFT，尾延遲（P95/P99）與 throughput 影響未充分討論。</li></ul></li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接呼應 <code>context-management.md</code> §Prompt Caching 核心原則</strong>：本庫規則要求「CLAUDE.md 內容 = 最穩定快取前綴，永遠放最前」，CacheWeaver 的 prefix tree greedy walk 是同一直覺的系統化實現——在 RAG 場景動態決定哪段 context 應擺在 HEAD 以最大化 cache 復用。</li><li><strong>對應 NLAH 原則（Right context &gt; more context）</strong>：CacheWeaver 不增減 evidence，只調整排列順序；這與「context 放 HEAD 或 TAIL，中間放動態狀態」的 NLAH 精神一致，說明 ordering 本身即是 context 管理的一個維度。</li><li><strong>對 subagent fan-out 場景的潛在啟示</strong>：多個 sub-agent 並行查詢共用知識庫時，若 LLM serving 層有 prefix cache，統一 evidence 排序策略可降低跨請求的 cache 碎片化；⚠️ 本庫目前無對應機制，屬未落地概念。</li><li><strong>⚠️ 域外注意</strong>：CacheWeaver 針對 vLLM serving engine 的 KV cache；Claude API（Anthropic 管理）的 prompt caching 實作細節不公開，本方法能否直接移植需進一步確認。</li></ul>',16)])])}const u=r(i,[["render",o]]);export{p as __pageData,u as default};
